import{_ as a,o as i,c as r,ag as t}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"Form Proposal workspace","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/index.md","filePath":"proposals/index.md"}'),s={name:"proposals/index.md"};function o(n,e,d,c,l,p){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="form-proposal-workspace" tabindex="-1">Form Proposal workspace <a class="header-anchor" href="#form-proposal-workspace" aria-label="Permalink to &quot;Form Proposal workspace&quot;">​</a></h1><p>This directory contains mutable design material. Some notes accompany exact unpublished candidate FormRefs; others describe possible future Forms or retained history. A document here is never itself a package, release, maturity claim, Host Support decision, or Service Offering.</p><p>Family design work lives in per-family subdirectories, authored under the shape-preserving boundary of <a href="./../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a> and selected by <a href="./../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>:</p><ul><li><a href="./edge/">Edge Platform Family</a> — the first family; its candidates are tracked by <a href="../forms/candidates/edge.forms.takoform.com/candidate-set.json"><code>../forms/candidates/edge.forms.takoform.com/candidate-set.json</code></a>. The group carries no version (<a href="./../spec/decisions/0049-a-form-versions-alone.html">decision 0049</a>), so a candidate is proposed in this tree and joins that one set rather than waiting for a generation to be minted around it.</li><li><a href="./function/">Regional Function Family</a> — regional FaaS, 4 current candidates.</li><li><a href="./container/">Serverless Container Family</a> — OCI-image services, 5 current candidates.</li><li><a href="./table/">Table Family</a> — key-addressed document tables, 1 current candidate.</li><li><a href="./queue/">Pull Queue Family</a> — pull-based at-least-once queues, 1 current candidate.</li><li><a href="./topic/">Topic Family</a> — fanout topics and queue subscriptions, 2 current candidates.</li><li><a href="./schedule/">Schedule Family</a> — standalone cron invocation, 1 current candidate.</li><li><a href="./vector/">Vector Family</a> — fixed-dimension vector indexes, 1 current candidate.</li></ul><p>All eight current versionless family candidate sets are closed by <a href="../forms/candidates/current-family-index.json"><code>../forms/candidates/current-family-index.json</code></a>: 31 exact Experimental <code>0.x</code> FormRefs in total. That generated index and the candidate bytes it names own the current identities. Proposal prose remains non-normative and reserves no additional identity. The pre-family flat Proposal set and its lifecycle registry were withdrawn with the pre-Beta epochs (<a href="./../spec/decisions/0042-the-pre-beta-epochs-are-withdrawn.html">decision 0042</a>); their documents stay in git history as design provenance and reserve no public identity.</p><p>Start a new family Proposal by copying <code>TEMPLATE.md</code> into the family&#39;s subdirectory under a descriptive lowercase filename. A Form enters the family only through the generated candidate set; the public-surface gate holds every hand-written inventory to that roster, so a Proposal without a candidate entry cannot leak into the published surface.</p><p>Before review, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/standard-form-conformance</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>Proposal review does not authorize publication. When a Proposal is withdrawn, remove its document unless a decision record needs to retain the design history; no public identity is reserved by a withdrawn Proposal.</p>',9)])])}const u=a(s,[["render",o]]);export{m as __pageData,u as default};
